import{_ as d,o as e,c as o,a0 as a}from"./chunks/framework.BtostX_-.js";const g=JSON.parse('{"title":"排序算法","description":"","frontmatter":{"title":"排序算法","icon":"order"},"headers":[],"relativePath":"zh/notes/sorts.md","filePath":"zh/notes/sorts.md","lastUpdated":1792777361000}'),s={name:"zh/notes/sorts.md"};function r(i,t,n,l,c,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="排序算法" tabindex="-1">排序算法 <a class="header-anchor" href="#排序算法" aria-label="Permalink to &quot;排序算法&quot;">​</a></h1><blockquote><p><a href="/algorithms/notes/sorts.html">English</a> | <strong>中文</strong></p></blockquote><p><code>sorts/go</code> 模块实现 7 种排序，全部为泛型（<code>golang.org/x/exp/constraints</code>）。</p><h2 id="实现位置" tabindex="-1">实现位置 <a class="header-anchor" href="#实现位置" aria-label="Permalink to &quot;实现位置&quot;">​</a></h2><ul><li>源码：<code>sorts/go/*.go</code></li><li>测试：<code>sorts/go/*_test.go</code></li></ul><h2 id="一览" tabindex="-1">一览 <a class="header-anchor" href="#一览" aria-label="Permalink to &quot;一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>算法</th><th>函数</th><th>平均复杂度</th><th>稳定性</th><th>备注</th></tr></thead><tbody><tr><td>冒泡</td><td><code>BubbleSort[T]</code></td><td>O(n²)</td><td>稳定</td><td></td></tr><tr><td>插入</td><td><code>InsertionSort[T]</code></td><td>O(n²)</td><td>稳定</td><td></td></tr><tr><td>选择</td><td><code>SelectionSort[T]</code></td><td>O(n²)</td><td>不稳定</td><td></td></tr><tr><td>归并</td><td><code>MergeSort[T]</code></td><td>O(n log n)</td><td>稳定</td><td></td></tr><tr><td>快排</td><td><code>QuickSort[T]</code></td><td>O(n log n)</td><td>不稳定</td><td>桶排序内部复用</td></tr><tr><td>计数</td><td><code>CountingSort[T]</code></td><td>O(n+k)</td><td>稳定</td><td>支持负数（按 min 偏移）</td></tr><tr><td>桶</td><td><code>BucketSort[T]</code></td><td>O(n+k)</td><td>稳定</td><td>桶内快排</td></tr></tbody></table><h2 id="历史坑位-已修复-回归用例在测试里" tabindex="-1">历史坑位（已修复，回归用例在测试里） <a class="header-anchor" href="#历史坑位-已修复-回归用例在测试里" aria-label="Permalink to &quot;历史坑位（已修复，回归用例在测试里）&quot;">​</a></h2><ul><li><strong>桶排序</strong>：桶序号要用「桶宽」整除而不是「桶数」，否则全负输入（如 <code>[-10..0]</code>）时下标越界 panic；末尾回拷必须扫满 <code>nBuckets</code> 个桶（<code>[0,100]</code> 这类稀疏输入会丢元素）。</li><li><strong>计数排序</strong>：计数数组必须按 <code>min</code> 偏移下标，否则负数直接越界（此 bug 曾被桶排序的 panic 掩盖）。</li></ul><h2 id="测试状态" tabindex="-1">测试状态 <a class="header-anchor" href="#测试状态" aria-label="Permalink to &quot;测试状态&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sorts/go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p>当前 7 个测试全部通过（含全负输入与稀疏输入用例）。</p>',12)])])}const k=d(s,[["render",r]]);export{g as __pageData,k as default};
